CREATE TABLE [dbo].[RepInChangeFlow](	  [date] SMALLDATETIME NOT NULL	, [time] VARCHAR(15) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [inboundId] SMALLINT NOT NULL	, [inbound] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [weekday_count] VARCHAR(20) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [count] INT NOT NULL	, [year] INT NOT NULL	, [month] INT NOT NULL	, [day] INT NOT NULL	, [hour] INT NOT NULL	, [minutes] INT NOT NULL	, CONSTRAINT [PK_RepInChangeFlow] PRIMARY KEY ([date] ASC, [inboundId] ASC))CREATE NONCLUSTERED INDEX [IX_RepInChangeFlow] ON [dbo].[RepInChangeFlow] ([date] ASC)